def pose(s,arm='right'):
    i=s.model.site('gripper0_'+arm+'_grip_site').id
    return s.data.site_xpos[i].copy(),s.data.site_xmat[i].reshape(3,3).copy()

def obj(s,name='obj'):
    return s.data.xpos[s.env.obj_body_id[name]].copy()

def target(s,p,R,arm='right',grip=None):
    a=s.targets.copy(); b=s.model.body('robot0_base').id
    rb=s.data.xmat[b].reshape(3,3); pb=s.data.xpos[b]; k=0 if arm=='right' else 6
    a[k:k+3]=rb.T@(np.asarray(p)-pb)
    a[k+3:k+6]=Rotation.from_matrix(rb.T@R).as_rotvec()
    if grip is not None: a[12+k:18+k]=grip
    return a

def move(s,p,R=None,n=40,arm='right',grip=None,hold=10):
    p0,R0=pose(s,arm); R=R0 if R is None else np.asarray(R)
    rr=Slerp([0,1],Rotation.from_matrix([R0,R]))
    for i in range(n):
        t=(i+1)/n; t=t*t*(3-2*t)
        s.step(target(s,p0+(np.asarray(p)-p0)*t,rr(t).as_matrix(),arm,grip))
    for i in range(hold): s.step(s.targets)
    status(s)

def status(s):
    print('step',len(s.actions),'success',s.success,'obj',np.round(obj(s),4),'pan',np.round(obj(s,'container'),4),'right',np.round(pose(s)[0],4),flush=True)

def contacts(s):
    cs=[]
